// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 amount) public {
        // Bound amount to avoid overflow issues
        vm.assume(amount > 0 && amount < 1e30);

        // Setup: make caller have some shares to claim
        // We'll first unpause via executeBatchDeposit (which unpauses)
        // Then call unpauseDeposit to keep unpaused state
        // Then call pauseDeposit to pause
        // Then verify claim reverts when paused

        // To make a valid claim, we need shares. We'll simulate by giving shares directly
        // by calling depositUsdc and then executeBatchStake + executeBatchDeposit
        // But for simplicity and to avoid external dependencies, we test the pause behavior
        // by first ensuring we can call claim after unpause

        // First, ensure contract is unpaused
        if (c.paused()) {
            // We need to unpause - in the mutant this might not work, but we can try
            // Instead, let's use a different approach: test that paused() returns false in mutant
            // even after pauseDeposit()
        }

        // Actually, let's test the core difference: after pauseDeposit(), paused() should return true
        // In the mutant it returns false

        // Set a keeper to call pause
        address keeper = address(0xBEEF);
        vm.prank(c.owner());
        c.setKeeper(keeper);

        // Ensure unpaused first
        if (c.paused()) {
            vm.prank(keeper);
            c.unpauseDeposit();
        }

        // Now pause
        vm.prank(keeper);
        c.pauseDeposit();

        // Now test claim - should revert in reference, might succeed in mutant
        // We'll use try/catch to catch the revert
        try c.claim(caller, amount) {
            // claim succeeded - this should only happen if paused() returned false (mutant)
            assertTrue(!c.paused(), "Claim should not succeed when paused");
        } catch {
            // claim reverted - this is expected when paused
            assertTrue(c.paused(), "Claim should revert when paused but paused state inconsistent");
        }
    }
}

